#!/usr/bin/env bash
# Verifier driver for step 11 (quiche 0.22.0).
#
# Generated by misc/quic-http3-stack-multiversion/tools/gen-step.py from the
# shared frame plus this step's group list. Edit the frame or the step part and
# regenerate; do not edit one copy in isolation. After Phase 3 opens on a step
# the generated copy becomes authoritative and the reviser edits it directly —
# `tools/carryover-check.sh` is what keeps the fifteen copies honest after that.
set -u
source /tests/helpers.sh

# --- verifier/step binding check -------------------------------------------
# Must be the first thing that runs: /etc/harbor-step-id names the image, the
# literal below names this tests/ tree, and a disagreement means the build
# context was served from another step's cache entry.
require_step 11
# --- end binding check ------------------------------------------------------

# ---------------------------------------------------------------------------
# 0. Crash path.
#
# Under `multi_step_reward_strategy = "mean"` a verifier that exits without a
# reward.json costs the whole trial the steps after it, so every exit from here
# on writes a complete scorecard and exits 0. `fail_everything` is the
# scorecard for a driver that died before it could measure anything.
#
# It reports `gate: 0` with an empty `gate_failures`, and that pairing is the
# signal: a gate of zero with no group named is the driver failing, not a
# candidate regressing. Anything that vetoes a real step names the group and
# quotes what it saw.
# ---------------------------------------------------------------------------
reported=0

fail_everything() {
    local reason="$1"
    printf '{"step":%s,"reward":0.000000,"gate":0,"score":0.000000,"gate_failures":[],"candidate_build":0,"harness_build":0,"fixture_ok":0,"budget_exhausted":0,"crate_dir":"unresolved","build_note":"%s","gate_groups":{},"scored_groups":{}}\n' \
        "${step_num:-0}" "$reason" > /logs/verifier/reward_details.json
    printf '{"reward":0.000000}\n' > /logs/verifier/reward.json
}

on_exit() {
    local status=$?
    if [ "${reported:-0}" -ne 1 ]; then
        fail_everything "the verifier driver exited with status $status before it reported: nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    fi
    exit 0
}
trap on_exit EXIT

step_num=11
step_tag=0.22.0
log_dir=/tmp/quiche-verifier-11
harness=/tmp/quiche-harness-11
assets=/tests/assets
mkdir -p "$log_dir"

# ---------------------------------------------------------------------------
# 1. Fixture integrity.
#
# The verifier-owned corpus — the RFC 9001 Appendix A vectors, the frame and
# QPACK vector files, and the e2e drivers — is a prerequisite for the groups
# that consume it, never a score point of its own. A broken corpus fails those
# groups; it must not short-circuit the independent ones or erase earned
# credit.
# ---------------------------------------------------------------------------
expected_assets_sha=8e210328f1d5df8d4916416acb4ca32325b11dd109d4dfaf490391748eaf40fd
expected_asset_files=33

actual_assets_sha=$(cd "$assets" && find . -type f -print0 | LC_ALL=C sort -z \
    | xargs -0 sha256sum | sha256sum | awk '{print $1}')
actual_asset_files=$(find "$assets" -type f | wc -l)

fixture_ok=1
[ "$actual_assets_sha" = "$expected_assets_sha" ] || fixture_ok=0
[ "$actual_asset_files" -eq "$expected_asset_files" ] || fixture_ok=0

# ---------------------------------------------------------------------------
# 2. Locating the candidate's transport crate.
#
# The library lives at the workspace root until milestone 6 and under
# `quiche/` from milestone 6 onward. Both layouts are accepted everywhere and
# the layout itself is scored by its own group at the step that introduces it,
# so a candidate that has not yet moved the tree loses that one group rather
# than every group in the step. TEST_INTERFACE.md states this probe.
# ---------------------------------------------------------------------------
crate_dir=unresolved
for cand in /app/quiche /app; do
    if [ -f "$cand/Cargo.toml" ] && grep -Eq '^[[:space:]]*name[[:space:]]*=[[:space:]]*"quiche"' "$cand/Cargo.toml"; then
        crate_dir=$cand
        break
    fi
done

workspace_root=/app
[ -f /app/Cargo.toml ] || workspace_root=$crate_dir

# ---------------------------------------------------------------------------
# 2. (continued) Which BoringSSL this tree was written against.
#
# The image pins the library this milestone's release pins, and the environment
# names it. At most steps that is the only copy and this loop does nothing.
#
# Where the QUIC callback struct changed shape across a step boundary, the
# image carries the previous release's pin as well. `SSL_QUIC_METHOD` is a
# struct of function pointers passed to `SSL_set_quic_method`: releases up to
# 0.1.0 declare four members, beginning `set_encryption_secrets`; from 0.3.0
# they declare five, beginning `set_read_secret` and `set_write_secret`. A tree
# of the older shape handed to a library of the newer one links cleanly -- the
# symbol exists and takes a pointer -- and then reads one member past the end
# of the struct, calling the wrong function for every callback. Nothing errors.
# The handshake simply never emits a ClientHello, and the step's inherited
# regression groups fail for a linkage reason wearing behaviour's clothes.
#
# So the shape is read out of the candidate's own `src/tls.rs` and the matching
# library selected. The test is deliberately two-sided -- the old name present
# AND the new names absent -- so a tree part-way through the conversion, or one
# that merely mentions the old name in a comment, keeps this release's library.
# The shape is read out of *live code*: `//` comments are stripped before the
# two greps run, so a migration note naming the old field cannot flip the pick.
# A candidate who does the work is unaffected: the environment already names
# the right one, and this loop never fires. It cannot manufacture a pass for
# the scored groups either; those ask for behaviour this milestone introduced,
# which no older library supplies.
#
# `.cargo/config.toml` in the workdir sets the same variable through cargo's
# `[env]` table, which without `force = true` yields to a variable already set
# in the environment -- so exporting here is enough, and the file stays honest
# about the default.
# ---------------------------------------------------------------------------
if [ -n "${QUICHE_BSSL_PATH:-}" ] && [ -f "$crate_dir/src/tls.rs" ] &&
    sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_encryption_secrets' &&
    ! sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_read_secret'; then
    for alt in /opt/bssl/*; do
        [ -d "$alt" ] || continue
        [ "$alt" = "$QUICHE_BSSL_PATH" ] && continue
        QUICHE_BSSL_PATH=$alt
        export QUICHE_BSSL_PATH
        break
    done
fi

# ---------------------------------------------------------------------------
# 2a. The time budget, and why these numbers.
#
# `task.toml` gives this step `[steps.verifier] timeout_sec = 3600`. If the
# verifier is killed by that timeout it never writes reward.json and the run is
# unattributable rather than a zero, so the work inside must provably fit
# whatever the candidate does:
#
#   verify the pinned asset corpus                               <   5 s
#   CANDIDATE_BUILD_TIMEOUT  one `cargo build` of /app, cold    <= 1000 s
#   EXAMPLES_BUILD_TIMEOUT   the best-effort examples pass      <=  240 s
#   APPS_BUILD_TIMEOUT       the best-effort app-package pass   <=  240 s
#   HARNESS_BUILD_TIMEOUT    one `cargo test --no-run` of the
#                            verifier-owned harness crate       <=  800 s
#   CASE_BUDGET_TOTAL        every gate check and every scored
#                            group together                     <= 1200 s
#   write the two JSON files                                     <   5 s
#                                                    worst case   3490 s
#
# PER_CASE_MAX is far above any real case and far below the aggregate: one
# hanging case costs its own group and at most 120 s of the shared pool, so a
# step with many hanging cases degrades group by group instead of taking the
# run down. BoringSSL and the whole dependency graph are prebuilt into the
# image, so the candidate build is the candidate's own code and nothing else.
CANDIDATE_BUILD_TIMEOUT=1000
EXAMPLES_BUILD_TIMEOUT=240
APPS_BUILD_TIMEOUT=240
HARNESS_BUILD_TIMEOUT=800
CASE_BUDGET_TOTAL=1200
PER_CASE_MAX=120

# ---------------------------------------------------------------------------
# 3. Build the candidate workspace once, before anything is scored.
#
# Recorded separately from the groups: every group runs against this build, so
# one compile error would otherwise be reported as N unrelated capability gaps.
# ---------------------------------------------------------------------------
candidate_build=0
if [ "$crate_dir" != unresolved ]; then
    # Default targets only -- libraries and binaries. Deliberately not
    # `--all-targets`: that would also compile the candidate's own test and
    # bench targets, so a broken test of theirs would fail the build and be
    # reported as every capability missing at once. Their tests are not what
    # this verifier measures.
    (cd "$workspace_root" && timeout "$CANDIDATE_BUILD_TIMEOUT" \
        cargo build --offline -j 4) \
        >"$log_dir/candidate-build.log" 2>&1 && candidate_build=1
    # The client and server lived under examples/ before they became their own
    # package. Best-effort and never fatal: at releases where they are bins the
    # build above already produced them, and at releases where there are no
    # examples this is a no-op.
    if [ "$candidate_build" -eq 1 ]; then
        (cd "$workspace_root" && timeout "$EXAMPLES_BUILD_TIMEOUT" \
            cargo build --offline --examples -j 4) \
            >"$log_dir/candidate-examples.log" 2>&1 || true
    fi
    # Later they moved out of examples/ and into a package of their own --
    # `tools/apps` first, then `apps`. Where that package is a workspace member
    # the build above already covered it; where it exists but the root manifest
    # has no [workspace] section, cargo never descends into it, so the tree
    # ships the client and server sources and produces neither binary. Building
    # the package where it sits covers that window, and builds more of the
    # candidate rather than asking less of it.
    #
    # Best-effort, like the examples pass, and bounded as one pass rather than
    # one per path: at a release whose lockfile predates this package's own
    # dependencies it cannot resolve offline at all, which is a property of the
    # pinned corpus and not a candidate defect. Building a non-member package
    # makes cargo write a lockfile beside its manifest; no group reads one.
    if [ "$candidate_build" -eq 1 ]; then
        apps_deadline=$(( $(date +%s) + APPS_BUILD_TIMEOUT ))
        for app in tools/apps apps; do
            [ -f "$workspace_root/$app/Cargo.toml" ] || continue
            left=$(( apps_deadline - $(date +%s) ))
            [ "$left" -gt 0 ] || break
            (cd "$workspace_root/$app" && timeout "$left" \
                cargo build --offline -j 4) \
                >"$log_dir/candidate-app-$(printf '%s' "$app" | tr / -).log" \
                2>&1 || true
        done
    fi
fi

# The client and server binaries are the process boundary most groups use.
# The harness resolves them itself, by name, from the CANDIDATE_* variables
# below -- the names are the step's own interface section's, and the harness
# applies them name-major over the directories it searches. The driver does
# not pre-resolve a binary and does not prefer any spelling of its own: a
# second resolution rule written here could only ever disagree with that one.
target_dir=${CARGO_TARGET_DIR:-$workspace_root/target}

export QUICHE_CRATE_DIR="$crate_dir"
export QUICHE_WORKSPACE="$workspace_root"
export QUICHE_ASSETS="$assets"
export QUICHE_LOGDIR="$log_dir"

# What `verifier::testkit` reads. The harness has to find the candidate's
# binaries, and in this image they are not under /app/target: CARGO_TARGET_DIR
# is set image-wide so the prewarmed dependency graph is reused, which moves
# every artefact to /opt/cargo-target. Telling the harness where the tree and
# the artefacts actually are keeps that an image detail instead of something
# each of the fifteen steps' test files has to know.
export CANDIDATE_ROOT="$workspace_root"
export CANDIDATE_TARGET_DIR="$target_dir"
# Scratch directories are deliberately never cleaned up: when a case fails, the
# document root, the captured stdout and the server log it left behind are the
# evidence. Rooting them in the log directory keeps them beside the case log.
export VERIFIER_SCRATCH="$log_dir/scratch"
mkdir -p "$VERIFIER_SCRATCH"

# ---------------------------------------------------------------------------
# 4. The throw-away harness crate.
#
# It lives outside /app so that a candidate cannot make its own acceptance pass
# by editing the cases, and so that nothing the harness needs is ever added to
# the candidate's manifest. It declares exactly one dependency — a path
# dependency on the candidate's own transport crate — so a harness build
# failure is always about the candidate's public surface and never about a
# registry.
# ---------------------------------------------------------------------------
# Does the candidate's manifest declare a Cargo feature by this name?
#
# Either an explicit entry under [features], or an optional dependency of the
# same name, which Cargo turns into a feature implicitly.
# Does the candidate's manifest declare `$2` as a feature?
#
# Three spellings are legal Cargo for "this crate can be built with a `qlog`
# feature", and all three have to be recognised or a correct manifest is read
# as not declaring it, the feature is dropped from the harness's own edge, and
# every `cap` group fails to link for a reason that is not the candidate's:
#
#   [features]
#   qlog = []
#
#   [dependencies]
#   qlog = { version = "..", optional = true }
#
#   [dependencies.qlog]
#   optional = true
#
# The third puts the name in the section header and never in field 1, which is
# why the spelling is tracked as well as the key.
declares_feature() {
    awk -v want="$2" '
        /^[[:space:]]*\[/ {
            sec = $1
            gsub(/^\[|\]$/, "", sec)
            section = sec
            dep_table = (sec == "dependencies." want || sec == "dev-dependencies." want \
                         || sec == "build-dependencies." want)
            next
        }
        $1 == want && $2 == "=" && section == "features" { found = 1 }
        $1 == want && $2 == "=" && section ~ /dependencies$/ \
            && $0 ~ /optional[ \t]*=[ \t]*true/ { found = 1 }
        dep_table && $1 == "optional" && $2 == "=" && $3 == "true" { found = 1 }
        END { exit found ? 0 : 1 }
    ' "$1"
}

prepare_harness() {
    rm -rf -- "$harness"
    mkdir -p "$(dirname "$harness")"
    # The whole tree, not a hand-listed subset: the harness is a two-member
    # workspace (the verifier crate and `support/`, the independent QUIC
    # implementation) and it carries its own `assets/` — the TLS keypair and
    # the RFC vectors the cases load through `testkit::asset`. Copying file
    # patterns instead would silently drop whichever of those a future step
    # starts using, and the resulting build failure would be charged to the
    # candidate.
    cp -a -- "$assets/harness" "$harness"
    # The only edit: the candidate's crate path, which is not known until the
    # probe above has run. Resolved here rather than in the checked-in manifest
    # so the manifest stays identical in all fifteen steps.
    sed -i "s#@@CRATE_DIR@@#$crate_dir#g" "$harness/Cargo.toml"
    # Optional feature requests, resolved against the candidate's own manifest.
    #
    # Cargo validates every feature reference while it resolves the graph,
    # before it compiles anything, so asking a milestone for a feature it does
    # not declare fails the whole harness build -- including the gate targets,
    # which never touch the feature. Names marked `# optional-feature:` in the
    # harness manifest are therefore kept only when the candidate declares
    # them. The scored case that needs one then fails to compile by itself,
    # which is the right answer for a candidate that has not built it.
    for feat in $(sed -n 's/^#[[:space:]]*optional-feature:[[:space:]]*//p' \
        "$harness/Cargo.toml"); do
        if declares_feature "$crate_dir/Cargo.toml" "$feat"; then
            printf 'kept optional feature %s\n' "$feat" \
                >>"$log_dir/harness-features.log"
        else
            sed -i "s/\"$feat\"[[:space:]]*,[[:space:]]*//; s/,[[:space:]]*\"$feat\"//; s/\"$feat\"//" \
                "$harness/Cargo.toml"
            printf 'dropped optional feature %s: the candidate does not declare it\n' \
                "$feat" >>"$log_dir/harness-features.log"
        fi
    done
    # No lockfile, on purpose. One authored against the reference tree would
    # pin the candidate's own dependency versions, turning a legitimate
    # difference in their manifest into a harness build failure that reads as
    # their fault. The registry cache is prewarmed, so resolving offline here
    # costs nothing.
    rm -f -- "$harness/Cargo.lock"
}

harness_build=0
if [ "$candidate_build" -eq 1 ]; then
    prepare_harness
    (cd "$harness" && timeout "$HARNESS_BUILD_TIMEOUT" \
        cargo test --offline --no-run -j 4) \
        >"$log_dir/harness-build.log" 2>&1 && harness_build=1
fi

# The case pool starts here, so a slow build cannot eat it.
case_deadline=$(( $(date +%s) + CASE_BUDGET_TOTAL ))
budget_exhausted=0

# remaining_budget -> seconds left in the shared pool, or 0
remaining_budget() {
    local r=$(( case_deadline - $(date +%s) ))
    [ "$r" -lt 0 ] && r=0
    printf '%s\n' "$r"
}

# run_case <log-name> <test-target> <test-fn>
#
# Each case is bounded by the smaller of PER_CASE_MAX and what is left of
# CASE_BUDGET_TOTAL, so the cases can never overrun that total however many of
# them hang. A killed case exits non-zero and scores that one group 0, which is
# the same outcome as any other failure; once the pool is spent the remaining
# groups are failed without running and the reason is recorded, which is still a
# zero rather than a lost run.
run_case() {
    local name="$1" target="$2" fn="$3" remaining limit status
    remaining=$(remaining_budget)
    if [ "$remaining" -le 5 ]; then
        budget_exhausted=1
        printf 'the aggregate case budget of %s s was exhausted before this case ran\n' \
            "$CASE_BUDGET_TOTAL" >"$log_dir/$name.log"
        return 1
    fi
    if [ ! -d "$harness" ]; then
        # The harness crate is assembled only after a candidate transport crate
        # has been located. When it was not, every case here would fail on `cd`
        # with a shell error in its log, which reads as a broken driver rather
        # than as a result. The group does fail -- but for a definite reason,
        # and the reason belongs on the group that fired it.
        {
            printf 'the harness crate was never assembled, so this case could not run.\n'
            printf 'assembly is skipped when no candidate transport crate was located\n'
            printf '(crate_dir=%s): there was nothing for the harness to link against.\n' "$crate_dir"
            printf 'This group fails for that reason, not for anything it asserts.\n'
        } >"$log_dir/$name.log"
        return 1
    fi
    limit=$PER_CASE_MAX
    [ "$remaining" -lt "$limit" ] && limit=$remaining
    (cd "$harness" && timeout "$limit" \
        cargo test --offline --test "$target" "$fn" -- --exact --nocapture) \
        >"$log_dir/$name.log" 2>&1
    status=$?
    [ "$status" -eq 0 ] || return "$status"
    # Every invocation asserts an exact executed count: a name filter that
    # matches nothing still exits 0, and would otherwise be scored as a pass.
    grep -q 'test result: ok\. 1 passed; 0 failed; 0 ignored' "$log_dir/$name.log"
}

# ---------------------------------------------------------------------------
# 5. The gate.
#
# Proof of life plus inherited regression: that the candidate builds, that its
# two binaries still complete a handshake and a transfer over real UDP, and
# that one deterministic end-to-end path per earlier milestone still works.
#
# Gate groups earn nothing. They only veto: if any one of them fails the step
# is worth zero however much of this step's own capability landed. That is
# deliberate. A candidate that implements this release by breaking the last one
# has not advanced the ladder, and an additive score would pay it for the parts
# that still happen to work.
#
# The corollary governs what is allowed in here. A gate case that can fail for
# a reason other than the candidate's code -- a wall clock, a host's CPU count,
# an unordered iteration read as ordered -- is not weak coverage, it is a step
# that randomly scores zero for everyone including the reference. Every case
# below is deterministic, and the ones that were not were deleted rather than
# demoted; NOTES.md lists them and why.
#
# Behaviour this step deliberately changes is likewise not in here. A migration
# left in the gate is a step whose own reference implementation fails it.
# ---------------------------------------------------------------------------
gate_ok=1
gate_log=$log_dir/gate.txt
: > "$gate_log"

gate_check() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$gate_log"
    else
        printf 'FAIL %s\n' "$name" >> "$gate_log"
        gate_ok=0
    fi
}

candidate_builds() { [ "$candidate_build" -eq 1 ]; }

# Every other gate group is a case or a driver and leaves `$log_dir/<name>.log`
# behind, which is where the scorer reads the reason a veto fired. This one is
# a flag set back in section 3, so give it the log the flag came from.
if [ -f "$log_dir/candidate-build.log" ]; then
    cp -f "$log_dir/candidate-build.log" "$log_dir/candidate-workspace-builds.log"
else
    # Section 3 runs cargo only when a quiche crate was located. When it was
    # not, no candidate-build.log exists, and copying it silently left this
    # group with no log at all -- which the scorer reports as "the case did not
    # run". That reads like a harness that failed to fire, when in fact the
    # group failed for a definite reason. A veto must carry its reason on the
    # group that fired it, so write it here rather than leave the scorer to
    # guess. The step-level build_note says the same thing; this puts it where
    # a reader looks first.
    {
        printf 'no cargo build was attempted: crate_dir=%s\n' "$crate_dir"
        printf 'no Cargo.toml declaring the package name `quiche` was found at\n'
        printf '/app or /app/quiche, so there was no transport crate to build.\n'
        printf 'This group fails by definition: proof-of-life cannot pass when\n'
        printf 'the candidate shipped no library to prove alive.\n'
    } > "$log_dir/candidate-workspace-builds.log"
fi
gate_check candidate-workspace-builds candidate_builds
# T3: The four-name accept list with its rejections -- `"BBR2"`, `"bbr2 "`, `"bbr3"` and `""` each `Err(quiche::Error::CongestionControl)` -- the `(0, 1, 2, 3)` discriminant tuple, a positive congestion window on the handshaken connection, and a 256 KiB transfer under each of the two ways of selecting the controller -- `set_cc_algorithm_name("bbr2")` and `set_cc_algorithm(BBR2)` -- completing byte-for-byte. Carried because this step takes every one of those algorithms apart and reassembles it a directory level down behind a new trait. Nothing in the package endangers BBRv2 more than this milestone does, and nothing yet carried step 10 -- this is its first re-run. Step 10's group also required the congestion window to be no smaller after the transfer than before it. That comparison is not carried into the gate. BBRv2 sizes its window from a bandwidth estimate and a minimum RTT taken off the real clock, and an in-memory pair has no propagation delay for either to be about, so both are readings of how promptly this host scheduled the drive loop; under enough load the pair sits long enough between rounds to enter ProbeRTT, whose window is four packets -- below where it started. `cap-bbr2` at step 10 still makes the comparison, where a miss costs that group's weight.
gate_check reg-10-bbr2 run_case reg-10-bbr2 reg reg_10_bbr2
# T1: The candidate's own `quiche-server` serves a 512 KiB body, the candidate's own `quiche-client` fetches it with `--http-version HTTP/0.9`, exits zero, and writes the body back byte-for-byte. T1, not T3: step 01 scored this over the process boundary and step 08 re-ran it there, and pinning HTTP/0.9 rather than letting the app negotiate keeps the observation the transport's. Carried because it is the simplest thing in the package that runs every byte through the rebuilt recovery path -- loss detection, the round-trip estimator now in its own file, the pacer now a directory down, and the acknowledgement bookkeeping that had to be re-plumbed to produce `acked_bytes`. If the rebuild broke, a half-megabyte transfer is where it shows. Re-seeded from step 08, the most recent step to carry it, and unchanged from it apart from the body seed.
gate_check reg-01-stream-transfer run_case reg-01-stream-transfer reg reg_01_stream_transfer
# T1: The mandatory process-boundary gate. The candidate's own `quiche-server` is started on a loopback port with `--listen`, `--cert`, `--key`, `--root` and `--no-retry`; the candidate's own `quiche-client` fetches a 2 KiB body from it over real UDP with `--no-verify`; the client exits zero and the bytes match what the server was given. The server is **not** given `--enable-pmtud`. The reference reads an `enable_pmtud` argument in `ServerArgs` and passes it to `Config::discover_pmtu`, but never declares the flag in `SERVER_USAGE`, so docopt refuses it -- `quiche-server --enable-pmtud` prints `Unknown flag: '--enable-pmtud'` and exits non-zero. Requiring the flag here would require a candidate to be *better* than the reference, which is not what a gate is for, and the group would fail against the Oracle. Nor is the refusal asserted anywhere else: as the milestone summary says, the flag's absence is recorded as the reference's behaviour and not required of the candidate, so a server that declares it is neither rewarded nor penalised. `cap-pmtud` scores the feature over a surface that can see it. Nothing else clever on purpose. If this group fails, every other T1 observation at this step is noise.
gate_check gate-endtoend run_case gate-endtoend gate gate_endtoend

# ---------------------------------------------------------------------------
# 6. The scored groups.
#
# This step's new capability, plus peripheral breadth. Each group is one
# coherent behaviour and is invoked separately, so a failure localises, and
# every group runs even after another has failed: a partial implementation
# keeps exactly the credit it earned.
#
# Weights live in `/tests/groups.json` and sum to one across the groups here,
# so this step's score is in [0, 1] and is the weighted fraction of its own new
# behaviour that works. Nothing in this section knows a weight -- it records
# PASS or FAIL per group and the scorer prices it -- so a revision that edits a
# group here cannot silently desync the driver from the manifest.
# ---------------------------------------------------------------------------
group_log=$log_dir/groups.txt
: > "$group_log"

score_if() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$group_log"
    else
        printf 'FAIL %s\n' "$name" >> "$group_log"
    fi
}

# T3: Four legs over in-memory `connect`/`accept` pairs, public API only. Both endpoints are configured with `set_max_send_udp_payload_size(1452)` and `set_max_recv_udp_payload_size(1452)` in every leg, so the only thing that differs between the two configurations is `discover_pmtu`. Every leg is a differential between those two connections, which is what stops a datagram budget, a pacing quantum or a buffer size from satisfying any of them. **On -- the server probes.** With `discover_pmtu(true)` on both sides the pair handshakes and settles, and the verifier records the length of every datagram each side produced. At least one **server** datagram is exactly 1452 bytes, and every server datagram is either at or under 1200 or exactly 1452, with nothing in between: ordinary output is held to the path estimate and only a padded probe leaves it. Measured against the reference: `[1200, 358, 439]` followed by nine 1452-byte probes. Neither the count nor the position is asserted. The count is a function of the congestion window at the moment the handshake completes, and the position is not "after the handshake" at all -- the reference emits its first probe *inside* the handshake flight, on the first `send` after HANDSHAKE_DONE. The window the group reads is therefore the whole connection up to the point application data is queued, not the part that follows `handshake()`. **Off -- nothing above the floor.** With `discover_pmtu(false)` on both sides, the same configuration and the same drive loop, **no** server datagram exceeds 1200 at all: `[1200, 358, 439]` and nothing else. This is the leg that makes the first one discriminating. **The client is clamped, not probing.** `Path::should_send_pmtu_probe` is gated on `handshake_confirmed && handshake_done_sent`, and only a server ever sets `handshake_done_sent`, so a client cannot leave the floor however it is configured. The consequence is visible, and it is the reverse of what the plan row guessed: with discovery *on*, a client pushing a 64 KiB transfer is limited to the 1200-byte estimate it can never raise, because `send` caps its output at `min(pmtud.get_current(), buffer)`; with discovery *off* the same client on the same transfer runs at 1452, because nothing caps it. Measured client histograms: `{43: 1, 483: 1, 904: 1, 936: 1, 1050: 1, 1200: 54}` on, and `{43: 1, 483: 1, 932: 1, 962: 1, 1452: 45}` off. Both directions are asserted -- the on leg as an upper bound, the off leg as an existence claim -- so the bound cannot be met by a connection that merely never had 1452 bytes to send. **Survival.** Both configurations carry the 64 KiB body to completion byte-for-byte with the stream finished, and neither end of the on-configuration pair is closed afterwards. A search that raises the estimate and then black-holes the connection is not discovery. The binary-search-on-loss leg is deliberately **absent**. Driving it requires discarding the probe and then advancing the connection until the loss is detected, and on an in-memory pair with no real clock the reference needed more timer ticks than a bounded test can justify before it re-probed at a smaller size -- measured: six `on_timeout` ticks with nine probes dropped produced no smaller probe. An assertion that cannot be driven deterministically against the reference does not belong in a group. `PathStats::pmtu` is **not** read. `Path::stats` reports `recovery.max_datagram_size()` there, which is the configured `max_send_udp_payload_size` from the moment the connection is created -- measured 1452 in *both* configurations before either has sent a packet -- so it cannot tell them apart. A group that asserted on it would be asserting on the configuration it had just set.
score_if cap-pmtud run_case cap-pmtud cap cap_pmtud
# T2/T3: The packet-number length field, read out of the candidate's own 1-RTT headers. The client is configured with `Config::log_keys()`, the verifier pulls `CLIENT_TRAFFIC_SECRET_0` out of the resulting NSS keylog, derives the generation-0 `PacketKeys`, and for every short-header datagram the client produces it removes header protection and reads the `len` the unmasked first byte declares. That is the field RFC 9000 Section 17.1 governs and the field this milestone changed, observed as a field rather than inferred from a total. Both sides set `set_initial_congestion_window_packets(600)` so the congestion window is never the thing under test. Before either phase runs, the verifier proves it has the right keys by opening one of the client's packets. If that fails the group says so in those words -- a key-schedule disagreement is not a packet-number fault and must not be reported as one. **Phase A, peer acknowledging.** 300 rounds, each one a small write from the client and the server's reply fed straight back, so acknowledgements keep arriving and the unacknowledged range stays tiny. **Every** client 1-RTT packet in this phase has a packet-number length of **1**, and the phase runs long enough that the client's packet number passes 255 -- which the verifier checks, by reconstructing the number, so "the packet number never got high enough" cannot be mistaken for "the length stayed narrow". Under step 10's magnitude rule the length steps to 2 at packet 255 and never returns, so the group fails against step 10, as it must. **Phase B, peer silent.** 500 further rounds on the *same* connection with the server's output discarded, so `largest_acked` freezes while the packet number keeps climbing. At least one client packet now has a packet-number length of **2**, and at least one still has **1** -- the width follows the unacknowledged range up, which is the whole content of the rule, and it does not simply jump to the maximum. The verifier also asserts that the phase was not blocked by flow control or congestion control, so "no packet was produced" cannot be mistaken for "the packet was narrow". Phase A is what a candidate that keeps the old magnitude rule fails. Phase B is what a candidate that hardcodes a one-byte packet number fails. Both are required and neither is sufficient. Datagram *lengths* were how this was first measured and they agree -- tree 11 gives `{53: 289, 58: 2, 59: 9}` in phase A where tree 10 gives `{53: 244, 54: 45, ...}` -- but the shipped assertion reads the header field, because a datagram length is a sum of many things and only one of them is under test here. Nothing is asserted about decoding. Decoding did not change, and a group that tested it would be scoring step 09's work as this step's.
score_if cap-pn-encode-exact run_case cap-pn-encode-exact cap cap_pn_encode_exact
# T2: The verifier owns the socket and is the peer. It builds a client Initial itself, sends it to the candidate's server, and counts the bytes that come back. Getting a *real* ClientHello into that Initial matters, and the group takes the long way round to do it. A stub CRYPTO payload draws only a small ACK from the server, which leaves even a factor of 1 non-binding and the group vacuous. So the verifier first stands up a throwaway `quiche::connect` client, takes its first Initial, decrypts it with `support::decrypt_initial(.., Perspective::Client)`, lifts the CRYPTO bytes out, and rebuilds them into its **own** Initial with `support::ClientInitial` -- same version, same connection IDs, padded to the mandatory 1200 -- which the verifier then encrypts with its own keys. The candidate's library is used to produce a ClientHello and for nothing else; the packet on the wire is the verifier's. One more piece of stage-setting, and it is what makes the group exact. The budget only discriminates when the server has more to send than it is allowed to, and the harness's single small certificate makes a first flight of only 1558 bytes -- under 3 x 1200, so the default and every factor from 2 upwards spend the same amount and the group could not tell 3 from 300. The verifier therefore writes the harness certificate eight times into one chain file and loads that as the server's chain, which takes the unconstrained flight to 7702 bytes. Nothing validates the chain: this group never runs a `quiche` client, and the throwaway one it borrows a ClientHello from sets `verify_peer(false)`. Seven legs against a server the verifier configures per leg, every one of them answering the same 1200-byte Initial: | leg | `set_max_amplification_factor` | required reply | | --- | --- | --- | | 1 | not called (default) | **exactly** 3600 bytes | | 2 | `5` | **exactly** 6000 bytes | | 3 | `4` | **exactly** 4800 bytes | | 4 | `3` | **exactly** 3600 bytes, and the same total as leg 1 | | 5 | `2` | **exactly** 2400 bytes | | 6 | `1` | **exactly** 1200 bytes, in exactly one datagram | | 7 | `0` | **nothing at all** | The right-hand column is not a table of constants baked into the test. It is computed as `min(free, factor * 1200)`, where `free` is measured in a calibration leg with the factor set to 1000 and the test refuses to run unless `free` exceeds `5 * 1200` -- so the legs bracket the default from both sides and a candidate whose certificate flight differs in length from the reference's is still scored against the formula rather than against the reference's numbers. This is the shape of the reference's own unit test, `server_sent == client_sent * FACTOR`, with `client_sent` fixed at 1200 by construction. Measured against the reference over the eight-certificate chain: 7702 bytes in seven datagrams unbounded, then 6000/4800/3600/2400/1200/0 at factors 5/4/3/2/1/0, and 3600 with the setter never called. Legs 1 and 4 together are what pin the default at exactly 3 rather than at "some number of at least 2": the default spends 3600 and stops, while 4800 and 6000 were both available and were both reached when asked for. A further check makes leg 6 a statement about content rather than about a number. The single datagram the server sends under factor 1 is decrypted with the verifier's own Initial keys and parsed: it is a server Initial carrying a CRYPTO frame whose first byte is `0x02`, a ServerHello. So the allowance truncates a real flight mid-stream; it does not suppress the flight, and it does not substitute padding or a CONNECTION_CLOSE. Note what this group does **not** claim. The 3x limit itself is not new at this milestone -- step 10's tree has the same constant, the same enforcement and the same unit assertion. Only the setter is new, so the legs that could pass without it (1 and 4's equality with it) are controls, and the score turns on the five legs that ask for a factor the default would not produce.
score_if cap-anti-amplification-factor run_case cap-anti-amplification-factor cap cap_anti_amplification_factor
# T4: An emitted artefact -- the crate's own directory layout, reached through `testkit::candidate_root()` -- checked against a fixed expectation table. This is the one toolbox exception to no-source-reading, and it is scored as layout and never as behaviour: not a line of any of these files is read, only whether the path exists. **Must exist:** ``` quiche/src/crypto/mod.rs quiche/src/crypto/boringssl.rs quiche/src/recovery/rtt.rs quiche/src/recovery/congestion/mod.rs quiche/src/recovery/congestion/reno.rs quiche/src/recovery/congestion/cubic.rs quiche/src/recovery/congestion/pacer.rs quiche/src/recovery/congestion/bbr/ quiche/src/recovery/congestion/bbr2/ ``` **Must not exist:** ``` quiche/src/crypto.rs quiche/src/recovery/reno.rs quiche/src/recovery/cubic.rs quiche/src/recovery/pacer.rs quiche/src/recovery/bbr/ quiche/src/recovery/bbr2/ ``` `quiche/src/recovery/mod.rs` is required to exist and is on neither list's interesting half -- it exists before and after, and saying so keeps a candidate from reading the "must not exist" list as "delete the directory". `quiche/src/crypto/openssl_quictls.rs` is **not** required. It is a second backend the reference happens to carry, and a candidate that builds only against BoringSSL -- which is what every other group in all fifteen steps requires -- has no reason to have written it. Both halves are needed. The first alone is satisfied by a candidate that copies files into the new places and leaves the old ones behind, which is not a reorganisation; the second alone is satisfied by deleting them. Nothing about `RttStats` or the congestion-control trait is asserted, in this group or anywhere in this step. Both are private, and a public assertion about a private type would be an assertion about the reference's source rather than about a contract.
score_if cap-recovery-and-crypto-layout run_case cap-recovery-and-crypto-layout cap cap_recovery_and_crypto_layout
# T3: Two legs: a fixed expectation table over the two new public enums, and one live protocol violation that binds the table to the wire. **The table.** Every variant of `quiche::WireErrorCode` and of `quiche::h3::WireErrorCode` is cast with `as u64` and compared against RFC 9000 Section 20.1 and RFC 9114 Section 8.1 -- seventeen values each, `0x0` through `0x10` and `0x100` through `0x110`, asserted in two batches so a wrong value reports which enum it was in. The names are the contract too: the test names every variant explicitly, so a candidate that ships sixteen of seventeen does not compile, which is the correct outcome for a missing public item. `quiche::Error::CryptoBufferExceeded` is named in the same leg for the same reason, and is asserted to be a variant distinct from the long-standing `quiche::Error::CryptoFail`: a connection that buffered more CRYPTO than it can hold has not failed to decrypt anything, and the two must not compare equal. **The wire.** The verifier drives an in-memory pair where the *client* runs `h3::Connection` and the *server* side is raw QUIC that the verifier writes bytes onto directly. On server-initiated unidirectional stream 3 the verifier writes, by hand: the control-stream type varint `0x00`, an empty SETTINGS frame (`0x04 0x00`), and then a DATA frame (`0x00 0x01 0x41`). RFC 9114 Section 7.2.1 does not permit DATA on a control stream. The client's `h3::Connection::poll` must return `Err(h3::Error::FrameUnexpected)`, and its transport connection's `local_error()` must carry `error_code == h3::WireErrorCode::FrameUnexpected as u64` -- that is, `0x105` -- with `is_app == true`. The verifier writes the control stream itself rather than reaching for the candidate's own control stream by number. Which stream id a candidate opens its control stream on is not part of any contract in this package, and a group that assumed 3 would be scoring an implementation detail. The `is_app` flag matters as much as the number does: `0x105` sent as a *transport* error would be `0x105` in the wrong namespace, and RFC 9114's codes travel in an application close. The private `Error::to_wire` mapping is not called, because it cannot be. Leg two is what proves the enum is the mapping's source of truth rather than a decorative table beside it.
score_if cap-wire-error-codes run_case cap-wire-error-codes cap cap_wire_error_codes
# T3: `Stats::acked_bytes` over an in-memory pair, in four steps: 1. immediately after `connect`, before a single packet is exchanged, the client's `acked_bytes` is **0**; 2. after the handshake completes it is greater than 0 -- the handshake itself is acknowledged traffic; 3. a 256 KiB body is sent and received byte-for-byte; afterwards the sender's `acked_bytes` is at least the length of the body. A lower bound, never an equality: the counter includes packet overhead and every handshake byte, and pinning a total would pin this build's packetisation; 4. reading it again without exchanging anything further returns the same value, and a further transfer only raises it. The counter is monotone. The receiving side is checked too: it has acknowledged very little application data of its own, so its `acked_bytes` is far below the body length while the sender's is above it. That asymmetry is what distinguishes the new counter from `sent_bytes` or `recv_bytes`, either of which a candidate might alias it onto. This is the one place the rebuilt recovery module is scored behaviourally, and it is scored through the number it now has to report rather than through where its source lives.
score_if cap-acked-bytes-stat run_case cap-acked-bytes-stat cap cap_acked_bytes_stat
# T3: `h3::Config::set_additional_settings` on one endpoint, observed through `peer_settings_raw()` on the other. The observation channel is not new -- `peer_settings_raw` exists at step 10 as well -- and that is deliberate: it means the group scores the new sending capability and not a new accessor. **Validation, before anything reaches a wire.** `set_additional_settings` returns `Err(h3::Error::SettingsError)` for each of the six identifiers the library sends itself -- `0x1`, `0x6`, `0x7`, `0x8`, `0x33`, `0x276` -- each tried in its own call, and for a single call containing the same unknown identifier twice. It returns `Ok(())` for a list of two distinct unknown identifiers. **Delivery.** A client configured with `[(0x4f4f, 0x1234), (0x9a9a, 0x5678)]` completes an HTTP/3 handshake with a server that has no additional settings of its own. The server's `peer_settings_raw()` is `Some`, contains both pairs with both values intact, and contains them in the order they were configured. The list also contains the identifiers the library sends on its own account, which is why membership and relative order are asserted rather than equality against a fixed list -- how many settings a conforming implementation sends unprompted is not this step's business. **The reverse direction** is checked once, with the server carrying `[(0x7f7f, 0x99)]` and the client reading it, so a candidate that wires the new setting into only one of the two roles fails. Nothing is asserted about the HTTP/2-reserved identifiers `0x0` and `0x2` through `0x5`. RFC 9114 requires a *receiver* to reject them, and the reference accepts them in `set_additional_settings` and lets the peer do the rejecting; a group that demanded rejection at the setter would be demanding something the reference does not do.
score_if cap-h3-additional-settings run_case cap-h3-additional-settings cap cap_h3_additional_settings

# ---------------------------------------------------------------------------
# 7. Report.
#
#     reward = gate x score
#
# `score.py` does the arithmetic against the manifest, because the two checks
# that matter are both about groups going missing -- a declared group with no
# recorded result, or a recorded result for a group nobody priced -- and both
# are easier to get right over parsed JSON than over shell word splitting. It
# prints the reward and writes reward_details.json, naming the gate group that
# vetoed the step and quoting what it saw.
#
# If it cannot run at all, that is a verifier defect and not a capability
# result, and the crash path in section 0 says so in those words.
# ---------------------------------------------------------------------------
score_input=$(printf '{"step_num":%d,"tag":"%s","log_dir":"%s","manifest":"/tests/groups.json","crate_dir":"%s","candidate_build":%s,"harness_build":%s,"fixture_ok":%s,"budget_exhausted":%s}\n' \
    "$step_num" "$step_tag" "$log_dir" "$crate_dir" \
    "$([ "$candidate_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$harness_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$fixture_ok" -eq 1 ] && echo true || echo false)" \
    "$([ "$budget_exhausted" -eq 1 ] && echo true || echo false)")

reward=$(printf '%s' "$score_input" | python3 /tests/score.py 2>"$log_dir/score.err")
score_status=$?

case "$reward" in
    0|0.*|1|1.0*) ;;
    *) reward='' ;;
esac

if [ "$score_status" -ne 0 ] || [ -z "$reward" ]; then
    fail_everything "the verifier could not score this step: score.py exited $score_status saying '$(tr -d '\n"\\' < "$log_dir/score.err" | tail -c 300)'. Nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    reported=1
    exit 0
fi

reported=1
report "$reward"
exit 0
